# Try the proper online tables API path through databricks CLI
databricks api post "/api/2.0/online-tables" --json '{
  "name": "workspace.mlpab3c56d5.scored50223c",
  "spec": {
    "source_table_full_name": "workspace.mlpab3c56d5.scored50223c",
    "primary_key_columns": [{"name": "request_id"}],
    "run_triggered": {}
  }
}' -o json 2>&1

# Fix the primary key format
databricks api post "/api/2.0/online-tables" --json '{
  "name": "workspace.mlpab3c56d5.scored50223c",
  "spec": {
    "source_table_full_name": "workspace.mlpab3c56d5.scored50223c",
    "primary_key_columns": ["request_id"],
    "run_triggered": {}
  }
}' -o json 2>&1

# Need to create a Lakebase project first, then a synced table
# Let me create a project with the right prefix
databricks postgres create-project --json '{
  "project_id": "mlpab3c56d5-odt",
  "display_name": "mlpab3c56d5_odt"
}' -o json 2>&1

databricks postgres create-project mlpab3c56d5-odt --json '{
  "display_name": "mlpab3c56d5_odt"
}' -o json 2>&1

# Check what synced_table fields are required
databricks postgres create-synced-table "workspace.mlpab3c56d5.scored50223c" --json '{
  "synced_table": {
    "branch": "projects/mlpab3c56d5-odt/branches/production",
    "source_table": "workspace.mlpab3c56d5.scored50223c"
  }
}' -o json 2>&1

# Try different field names
databricks postgres create-synced-table "workspace.mlpab3c56d5.scored50223c" --json '{
  "source_table_full_name": "workspace.mlpab3c56d5.scored50223c",
  "branch": "projects/mlpab3c56d5-odt/branches/production"
}' -o json 2>&1

# Try debug mode to see what API call is being made
databricks postgres create-synced-table "workspace.mlpab3c56d5.scored50223c" --json '{
  "SyncedTable": {
    "branch": "projects/mlpab3c56d5-odt/branches/production"
  }
}' -o json --debug 2>&1 | head -30

# Use the API directly with the correct field structure
databricks api post "/api/2.0/postgres/synced_tables" --json '{
  "synced_table_id": "workspace.mlpab3c56d5.scored50223c",
  "synced_table": {
    "branch": "projects/mlpab3c56d5-odt/branches/production"
  }
}' -o json 2>&1

# The synced_table_id should be a query param based on debug output
# Let me check what the SyncedTable sub-fields are
databricks api post "/api/2.0/postgres/synced_tables?synced_table_id=workspace.mlpab3c56d5.scored50223c" --json '{
  "synced_table": {
    "branch": "projects/mlpab3c56d5-odt/branches/production"
  }
}' -o json 2>&1

# The branch seems to be rejected; need to find the right field name
# Try different subfields
databricks api post "/api/2.0/postgres/synced_tables?synced_table_id=workspace.mlpab3c56d5.scored50223c" --json '{
  "synced_table": {
    "branch_resource_name": "projects/mlpab3c56d5-odt/branches/production",
    "source_table_full_name": "workspace.mlpab3c56d5.scored50223c"
  }
}' -o json 2>&1

# Try using the direct API post with full body structure
databricks api post "/api/2.0/postgres/synced_tables?synced_table_id=workspace.mlpab3c56d5.scored50223c" --json '{
  "synced_table": {
    "branch_id": "projects/mlpab3c56d5-odt/branches/production",
    "project_id": "mlpab3c56d5-odt"
  }
}' -o json 2>&1

databricks api post "/api/2.0/postgres/synced_tables?synced_table_id=workspace.mlpab3c56d5.scored50223c" --json '{
  "synced_table": {
    "project": "projects/mlpab3c56d5-odt",
    "source": "workspace.mlpab3c56d5.scored50223c"
  }
}' --debug 2>&1 | grep -E "> |< " | head -30

# Register the Lakebase database as a UC catalog with prefixed name
databricks postgres create-catalog "mlpab3c56d5-lbcat" \
  --json '{
    "spec": {
      "postgres_database": "databricks_postgres",
      "branch": "projects/mlpab3c56d5-odt/branches/production"
    }
  }' -o json 2>&1

# Create the synced table - this syncs the Delta table into Lakebase for online access
databricks postgres create-synced-table "mlpab3c56d5-lbcat.public.scored50223c" \
  --json '{
    "spec": {
      "source_table_full_name": "workspace.mlpab3c56d5.scored50223c",
      "primary_key_columns": ["request_id"],
      "scheduling_policy": "SNAPSHOT",
      "branch": "projects/mlpab3c56d5-odt/branches/production",
      "postgres_database": "databricks_postgres",
      "create_database_objects_if_missing": true,
      "new_pipeline_spec": {
        "storage_catalog": "workspace",
        "storage_schema": "mlpab3c56d5"
      }
    }
  }' -o json 2>&1
